```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure counts as zero characters fetched.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat at {}: fetched {} characters from {}",
            seconds, fetched, feed_url
        );
        let notified = notifier::notify(&message);

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
